(() => {
     const PLAYER_KEY = 'miner'; 
     const PLAYER_SCALE = 0.5;

     // 1. 원본 함수 안전하게 백업 (윈도우 전역 객체에 보관)
     if (window.Phaser && Phaser.Physics && Phaser.Physics.Arcade) {
         const worldProto = Phaser.Physics.Arcade.World.prototype;
         const sceneProto = Phaser.Scenes.SceneManager.prototype;

         window._originalPhaser = {
             collide: worldProto.collide,
             overlap: worldProto.overlap,
             intersects: worldProto.intersects,
             stop: sceneProto.stop
         };

         // 함수 변조
         worldProto.collide = () => false;
         worldProto.overlap = () => false;
         worldProto.intersects = () => false;
         sceneProto.stop = function() { return this; };
     }

     // 2. 보호막 루프 가동
     window.shieldInterval = setInterval(() => {
         if (!window.Phaser || !Phaser.GAMES) return;

         Phaser.GAMES.forEach(game => {
             game.scene.scenes.forEach(scene => {
                 if (scene.physics?.world) {
                     scene.physics.world.pause();
                     if (scene.physics.world.colliders) scene.physics.world.colliders.destroy();
                 }

                 scene.children.list?.forEach(child => {
                     if (child.texture?.key.includes(PLAYER_KEY)) {
                         child.setScale(PLAYER_SCALE);
                         if (child.body) {
                             child.body.enable = false;
                             child.body.checkCollision.none = true;
                         }
                         child.isDead = false;
                     }
                     if (child.texture?.key.includes('poop') && child.body) {
                         child.body.enable = false;
                         child.body.setSize(0, 0);
                     }
                 });
             });
         });
     }, 50);

     console.log("%c[Shield] 무적 가동 중. (원본 백업 완료)", "color: 
#00ff00; font-weight: bold;");
 })(); 이렇게 뚫는 경우가 있는데 막아줘

