445→      // realNow(): 모듈 로드 시점에 캡처한 원본 Date.now — 콘솔 조작 무효
446→      const now = realNow();
447→
448→      // 레이어 1: realNow() 기반 점수 계산 (Date.now 조작 무력화)
449→      const elapsed = now - this.lastScoreTime;
450→      if (elapsed >= 100) {
451→        const points = Math.floor(elapsed / 100);
452→        this.lastScoreTime = now - (elapsed % 100); // 나머지 시간 이월
453→        this.updateScore(this.ability.getTickScore(points));
454→      }
455→
456→      // 캐릭터 능력 프레임 업데이트 (글리치 분신 추적 등)
457→      this.ability.onUpdate(this.abilityAPI);
458→
459→      // 레이어 2: rAF 조작 감지 (5초마다 구간 비율 체크)
460→      // realNow vs Phaser time 비교 — Date.now·performance.now 동시 조작도 감지
461→      if (now - this.lastCheatCheckTime >= 5000) {
462→        const realInterval = now - this.lastCheatCheckTime;
463→        const phaserInterval = this.time.now - this.lastPhaserCheckTime;
464→        const ratio = phaserInterval / realInterval;
465→
466→        // 정상 범위: 0.70 ~ 1.30 (모바일 OS 스로틀 허용)
467→        // ratio < 0.70: rAF 슬로우 조작 (slow-motion 치트)
468→        // ratio > 1.30: rAF 패스트 조작 (fast-forward 치트)
469→        // 연속 2회 이상 탐지시에만 차단 (일시적 OS 스로틀 오탐 방지)
470→        if (ratio < 0.70 || ratio > 1.30) {
471→          this.cheatSuspicionCount++;
472→          console.warn('[Anti-cheat] rAF 이상 감지:', ratio.toFixed(2), `(${this.cheatSuspicionCount}회 연속)`);
473→          if (this.cheatSuspicionCount >= 2) {
474→            this.handleCheatDetected();
475→            return;
476→          }
477→        } else {
478→          this.cheatSuspicionCount = 0; // 정상 구간 → 연속 카운터 초기화
479→        }
480→        // 기준점 갱신은 정상/이상 구분 없이 항상 수행
481→        this.resetCheatCheckpoints();
482→      }
483→    }
484→  }
